const sections = ['Inicio', 'Documentos', 'Proyectos', 'Equipos', 'Reportes'];
const [tab, setTab] = useState('Inicio');
// La pestaña elegida del menú ocupa el último lugar visible
const visible = sections.indexOf(tab) < 3 ? sections.slice(0, 3) : [...sections.slice(0, 2), tab];
const hidden = sections.filter((section) => !visible.includes(section));

<Tabs value={tab} onValueChange={(value) => setTab(value)}>
  <TabList
    aria-label="Secciones"
    overflow={
      <TabOverflow label="Más secciones">
        {hidden.map((section) => (
          <DropdownMenuItem key={section} onSelect={() => setTab(section)}>
            {section}
          </DropdownMenuItem>
        ))}
      </TabOverflow>
    }
  >
    {visible.map((section) => (
      <Tab key={section} value={section}>
        {section}
      </Tab>
    ))}
  </TabList>
  {sections.map((section) => (
    <TabPanel key={section} value={section}>
      Contenido de {section}.
    </TabPanel>
  ))}
</Tabs>
